-- Session A: provisional write, not yet committed
BEGIN;
UPDATE accounts SET balance = balance - 100 WHERE id = 1;
-- holds exclusive write lock on row 1, does NOT commit yet

-- Session B: dirty read allowed only at READ UNCOMMITTED
SET TRANSACTION ISOLATION LEVEL READ UNCOMMITTED;
BEGIN;
SELECT balance FROM accounts WHERE id = 1; -- may see the -100
COMMIT;

-- Session A then undoes everything Session B just saw
ROLLBACK; -- Session B acted on a balance that never existed
